// Writes crates/cli/src/run/mime.rs: the extension table of `mime-types`, which `FSUtil.mimeType` uses to type
// `run -f` attachments (packages/util/src/fs-util.ts). Sorted by extension for a binary search.
import { createRequire } from "node:module"

const require = createRequire(new URL("../../../util/package.json", import.meta.url).pathname)
const types: Record<string, string> = require("mime-types").types
const entries = Object.entries(types).toSorted(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
const lines = [
  "// Generated by script/gen/mime.ts from the `mime-types` package. Do not edit.",
  "",
  "/// `(extension, type)`, sorted by extension.",
  "pub const TYPES: &[(&str, &str)] = &[",
  ...entries.map(([extension, type]) => `    (${JSON.stringify(extension)}, ${JSON.stringify(type)}),`),
  "];",
  "",
]

const file = new URL("../../crates/cli/src/run/mime.rs", import.meta.url).pathname
await Bun.write(file, lines.join("\n"))
console.log(`mime: ${entries.length} extensions`)
